import { FieldDescription, FieldSet, FieldTitle } from '@/components/ui/field';
import { Icon } from '@/components/ui/icon';
import {
  InputGroup,
  InputGroupAddon,
  InputGroupInput,
  InputGroupText,
} from '@/components/ui/input-group';
import { cn } from '@/lib/utils';
import { inputGroupFieldConfig } from './input-group-config';

function LeadingIcon({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <InputGroupAddon align="inline-start">
      <InputGroupText>{children}</InputGroupText>
    </InputGroupAddon>
  );
}

export function InputGroupSizes() {
  const sizes = [
    {
      label: 'Small',
      size: 'sm' as const,
    },
    {
      label: 'Default',
      size: 'default' as const,
    },
    {
      label: 'Large',
      size: 'lg' as const,
    },
  ];
  return (
    <div className="space-y-6">
      {sizes.map(({ size }) => {
        const {
          label: labelClass,
          description,
          gap,
          iconSize,
        } = inputGroupFieldConfig[size];
        const inlineLabelClass = cn(labelClass, size !== 'sm' && 'mb-[-4px]');
        return (
          <div key={size} className="flex gap-6">
            <FieldSet className={`w-[240px] ${gap}`}>
              <FieldTitle className={labelClass}>Label</FieldTitle>
              <InputGroup size={size}>
                <LeadingIcon>
                  <Icon icon="search" size={iconSize} className="icon" />
                </LeadingIcon>
                <InputGroupInput size={size} placeholder="Placeholder" />
              </InputGroup>
              <FieldDescription className={description}>
                Helper text
              </FieldDescription>
            </FieldSet>

            <FieldSet className={`w-[240px] ${gap}`}>
              <FieldTitle className={inlineLabelClass}>Label</FieldTitle>
              <InputGroup variant="inline" size={size}>
                <LeadingIcon>
                  <Icon icon="search" size={iconSize} className="icon" />
                </LeadingIcon>
                <InputGroupInput
                  variant="inline"
                  size={size}
                  placeholder="Placeholder"
                />
              </InputGroup>
              <FieldDescription className={description}>
                Helper text
              </FieldDescription>
            </FieldSet>
          </div>
        );
      })}
    </div>
  );
}

import { FieldDescription, FieldSet, FieldTitle } from '@/components/ui/field';
import { Icon } from '@/components/ui/icon';
import {
  InputGroup,
  InputGroupAddon,
  InputGroupInput,
  InputGroupText,
} from '@/components/ui/input-group';
import { cn } from '@/lib/utils';

export function InputGroupStatusStates() {
  const inlineLabelClass = cn(
    'label-regular-primary text-fg-secondary',
    'mb-[-4px]',
  );
  const statuses = [
    {
      label: 'Error',
      icon: 'cancel',
      statusColor: 'text-status-error',
      defaultInputProps: {
        'aria-invalid': true,
        placeholder: 'Placeholder',
      } as const,
      inlineInputProps: {
        'aria-invalid': true,
        placeholder: 'Placeholder',
      } as const,
      defaultGroupClass: '',
      inlineGroupClass: '',
    },
    {
      label: 'Warning',
      icon: 'info',
      statusColor: 'text-status-warning',
      defaultInputProps: {
        placeholder: 'Placeholder',
      },
      inlineInputProps: {
        placeholder: 'Placeholder',
      },
      defaultGroupClass: '!border-status-warning !border',
      inlineGroupClass: '!border-b-status-warning !border-b',
    },
    {
      label: 'Success',
      icon: 'check_circle',
      statusColor: 'text-status-success',
      defaultInputProps: {
        placeholder: 'Placeholder',
      },
      inlineInputProps: {
        placeholder: 'Placeholder',
      },
      defaultGroupClass: '!border-status-success !border',
      inlineGroupClass: '!border-b-status-success !border-b',
    },
  ];
  return (
    <div className="space-y-6">
      {statuses.map(
        ({
          label,
          icon: statusIcon,
          statusColor,
          defaultInputProps,
          inlineInputProps,
          defaultGroupClass,
          inlineGroupClass,
        }) => (
          <div key={label} className="flex gap-6">
            <FieldSet className="w-[240px] gap-2">
              <FieldTitle className="label-regular-primary text-fg-secondary">
                Label
              </FieldTitle>
              <InputGroup className={defaultGroupClass || undefined}>
                <InputGroupInput {...defaultInputProps} />
                <InputGroupAddon align="inline-end">
                  <InputGroupText>
                    <Icon icon={statusIcon} size="sm" className={statusColor} />
                  </InputGroupText>
                </InputGroupAddon>
              </InputGroup>
              <FieldDescription
                className={`paragraph-regular-primary text-fg-tertiary ${statusColor}`}>
                Feedback message here
              </FieldDescription>
            </FieldSet>

            <FieldSet className="w-[240px] gap-2">
              <FieldTitle className={inlineLabelClass}>Label</FieldTitle>
              <InputGroup
                variant="inline"
                className={inlineGroupClass || undefined}>
                <InputGroupInput variant="inline" {...inlineInputProps} />
                <InputGroupAddon align="inline-end">
                  <InputGroupText>
                    <Icon icon={statusIcon} size="sm" className={statusColor} />
                  </InputGroupText>
                </InputGroupAddon>
              </InputGroup>
              <FieldDescription
                className={`paragraph-regular-primary text-fg-tertiary ${statusColor}`}>
                Feedback message here
              </FieldDescription>
            </FieldSet>
          </div>
        ),
      )}
    </div>
  );
}
